  1 // Serializes one frame's DOM into compact text for the model, with refs for interactive elements.
  2 // Rules (docs/05-browser-playbook.md): drop aria-hidden decoys and closed dialogs; keep tooltips (via
  3 // aria-describedby), collapsed <details> content, canvas/role=img labels, ::before data-labels, <time datetime>;
  4 // restore logical order (aria-posinset / CSS order); strip zero-width characters.
  5 (opts) => {
  6   const prefix = opts.prefix || "e";
  7   const ZW = /[​-‍⁠﻿­]/g;
  8   const clean = (s) => (s || "").replace(ZW, "").replace(/ /g, " ").replace(/\s+/g, " ").trim();
  9   const SKIP = new Set(["SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE", "HEAD", "META", "LINK"]);
 10   const BLOCK = new Set(["P", "DIV", "SECTION", "ARTICLE", "MAIN", "ASIDE", "HEADER", "FOOTER", "NAV", "UL", "OL",
 11     "LI", "DL", "DT", "DD", "FORM", "FIELDSET", "LEGEND", "TABLE", "THEAD", "TBODY", "TFOOT", "TR", "H1", "H2", "H3",
 12     "H4", "H5", "H6", "PRE", "BLOCKQUOTE", "DETAILS", "SUMMARY", "DIALOG", "CAPTION", "FIGURE", "BR", "HR", "LABEL"]);
 13   let n = 0;
 14   document.querySelectorAll("[data-agent-ref]").forEach((e) => e.removeAttribute("data-agent-ref"));
 15 
 16   const byId = (id) => (id ? document.getElementById(id) : null);
 17   const describedTexts = (el) => {
 18     const ids = (el.getAttribute("aria-describedby") || "").split(/\s+/).filter(Boolean);
 19     return ids.map((id) => clean(byId(id)?.textContent)).filter(Boolean);
 20   };
 21   const referencedTooltip = new Set();
 22   document.querySelectorAll("[aria-describedby]").forEach((el) =>
 23     (el.getAttribute("aria-describedby") || "").split(/\s+/).forEach((id) => id && referencedTooltip.add(id)));
 24 
 25   const styleOf = (el) => { try { return getComputedStyle(el); } catch { return null; } };
 26   const cssHidden = (el) => {
 27     if (el.hidden) return true;
 28     const cs = styleOf(el);
 29     return !!cs && (cs.display === "none" || cs.visibility === "hidden");
 30   };
 31   const isInteractive = (el) => {
 32     const t = el.tagName;
 33     if (t === "A") return el.hasAttribute("href");
 34     if (["BUTTON", "SELECT", "TEXTAREA"].includes(t)) return true;
 35     if (t === "INPUT") return el.type !== "hidden";
 36     if (t === "SUMMARY") return true;
 37     const role = el.getAttribute("role");
 38     return ["button", "link", "menuitem", "tab", "checkbox", "radio", "option", "switch"].includes(role);
 39   };
 40   const ref = (el) => { const r = prefix + (++n); el.setAttribute("data-agent-ref", r); return r; };
 41 
 42   // Accessible name of a control.
 43   const labelText = (el) => {
 44     const parts = [];
 45     const walk = (node) => {
 46       if (node.nodeType === 3) { parts.push(node.textContent); return; }
 47       if (node.nodeType !== 1 || SKIP.has(node.tagName)) return;
 48       if (node.getAttribute("aria-hidden") === "true") return;
 49       if (node !== el && ["INPUT", "SELECT", "TEXTAREA", "BUTTON"].includes(node.tagName)) return;
 50       if (node.getAttribute("data-label")) { parts.push(node.getAttribute("data-label")); return; }
 51       if (node.getAttribute("role") === "img" && node.getAttribute("aria-label")) { parts.push(node.getAttribute("aria-label")); return; }
 52       node.childNodes.forEach(walk);
 53     };
 54     walk(el);
 55     return clean(parts.join(" "));
 56   };
 57   const nameOf = (el) => {
 58     const aria = el.getAttribute("aria-label");
 59     if (aria) return clean(aria);
 60     const lb = el.getAttribute("aria-labelledby");
 61     if (lb) return clean(lb.split(/\s+/).map((id) => byId(id)?.textContent || "").join(" "));
 62     if (el.labels && el.labels.length) return labelText(el.labels[0]);
 63     if (["INPUT", "TEXTAREA", "SELECT"].includes(el.tagName)) return clean(el.placeholder || el.name || el.title || "");
 64     return clean(labelText(el) || el.title || el.value || "");
 65   };
 66 
 67   const controlLine = (el, hiddenCtx) => {
 68     const t = el.tagName;
 69     const r = ref(el);
 70     const flags = [];
 71     if (el.disabled || el.closest("[inert]") || el.closest("fieldset[disabled]")) flags.push("disabled");
 72     if (hiddenCtx) flags.push("hidden-until-hover/open");
 73     const info = describedTexts(el);
 74     let s;
 75     if (t === "A") {
 76       const href = el.getAttribute("href");
 77       s = `[${r}] link "${nameOf(el)}" -> ${href}` + (el.target ? ` (target=${el.target})` : "");
 78     } else if (t === "SELECT") {
 79       const opts = [...el.options].map((o) => (o.selected ? `*${clean(o.textContent)}*` : clean(o.textContent)) + (o.value !== clean(o.textContent) ? `{${o.value}}` : ""));
 80       s = `[${r}] select "${nameOf(el)}" options: ${opts.join(" | ")}`;
 81     } else if (t === "TEXTAREA") {
 82       s = `[${r}] textarea "${nameOf(el)}" value="${clean(el.value)}"`;
 83     } else if (t === "INPUT") {
 84       const ty = el.type;
 85       if (ty === "checkbox" || ty === "radio") s = `[${r}] ${ty} "${nameOf(el)}" ${el.checked ? "[x]" : "[ ]"}`;
 86       else if (ty === "range") s = `[${r}] slider "${nameOf(el)}" value=${el.value} min=${el.min || 0} max=${el.max || 100}`;
 87       else if (ty === "submit" || ty === "button") s = `[${r}] button "${clean(el.value) || nameOf(el)}"`;
 88       else s = `[${r}] input[${ty}] "${nameOf(el)}" value="${clean(el.value)}"`;
 89     } else if (t === "SUMMARY") {
 90       const d = el.parentElement;
 91       s = `[${r}] summary "${labelText(el)}" (${d && d.open ? "open" : "collapsed; content shown below"})`;
 92     } else {
 93       const role = el.getAttribute("role") || t.toLowerCase();
 94       s = `[${r}] ${role === "button" || t === "BUTTON" ? "button" : role} "${nameOf(el)}"`;
 95       if (el.getAttribute("aria-expanded")) s += ` expanded=${el.getAttribute("aria-expanded")}`;
 96     }
 97     if (flags.length) s += ` (${flags.join(", ")})`;
 98     if (info.length) s += ` [info: ${info.join(" / ")}]`;
 99     return s;
100   };
101 
102   const out = [];
103   let line = [];
104   const flush = () => { const s = clean(line.join(" ")); if (s) out.push(s); line = []; };
105   const emit = (s) => { if (s) line.push(s); };
106 
107   const orderedChildren = (el) => {
108     const kids = [...el.childNodes];
109     const keyed = kids.map((k, i) => {
110       if (k.nodeType !== 1) return { k, i, key: 0 };
111       const pos = k.getAttribute("aria-posinset");
112       const ord = parseInt(styleOf(k)?.order || "0", 10) || 0;
113       return { k, i, key: pos ? parseInt(pos, 10) : ord };
114     });
115     if (keyed.some((x) => x.key !== 0)) keyed.sort((a, b) => a.key - b.key || a.i - b.i);
116     return keyed.map((x) => x.k);
117   };
118 
119   const walk = (node, hiddenCtx) => {
120     if (node.nodeType === 3) { if (!hiddenCtx) emit(node.textContent.replace(ZW, "")); return; }
121     if (node.nodeType !== 1) return;
122     const el = node;
123     const t = el.tagName;
124     if (SKIP.has(t)) return;
125     if (el.getAttribute("aria-hidden") === "true") return;               // decoys and decoration
126     if (t === "DIALOG" && !el.open) return;                               // closed popups
127     const role = el.getAttribute("role");
128     if (role === "tooltip" && el.id && referencedTooltip.has(el.id)) return; // shown as [info: …] on its trigger
129     const hidden = hiddenCtx || cssHidden(el);
130     // Content of collapsed <details> is not rendered but is real content: keep it.
131     const inClosedDetails = !!el.closest("details:not([open])") && t !== "SUMMARY";
132     const effHidden = hidden && !(inClosedDetails && !el.hidden && styleOf(el)?.display !== "none");
133     const block = BLOCK.has(t);
134     if (block) flush();
135     if (t === "IFRAME" || t === "FRAME") {
136       emit(`[iframe "${clean(el.title || el.name)}" src=${el.getAttribute("src") || ""}${el.hasAttribute("srcdoc") ? " (srcdoc)" : ""}] (content listed as its own frame)`);
137       flush(); return;
138     }
139     if (/^H[1-6]$/.test(t) && !effHidden) emit("#".repeat(+t[1]));
140     if (t === "DIALOG" || role === "dialog" || role === "alertdialog") {
141       emit(`[DIALOG OPEN "${nameOf(el)}"]`); flush();
142     }
143     if (isInteractive(el)) {
144       if (!effHidden || t === "A" || t === "BUTTON") { flush(); out.push(controlLine(el, effHidden)); }
145       return;  // the control line carries its name; no need to walk inside
146     }
147     if (t === "LABEL" && el.querySelector("input,select,textarea") && !effHidden) {
148       el.querySelectorAll("input,select,textarea").forEach((c) => { if (c.type !== "hidden") { flush(); out.push(controlLine(c, false)); } });
149       flush(); return;  // the label text is already the controls' name
150     }
151     if (effHidden) {
152       // Hidden subtree: only surface controls (menus that open on hover), never hidden text.
153       el.querySelectorAll("a[href],button").forEach((c) => {
154         if (c.closest("[aria-hidden='true']") || c.closest("dialog:not([open])")) return;
155         flush(); out.push(controlLine(c, true));
156       });
157       return;
158     }
159     if (t === "CANVAS" || t === "IMG" || t === "SVG" || role === "img") {
160       const label = clean(el.getAttribute("aria-label") || el.getAttribute("alt") || el.getAttribute("title") || (t === "CANVAS" ? el.textContent : ""));
161       emit(label ? `[${t === "IMG" || t === "CANVAS" ? t.toLowerCase() : "img"}: ${label}]` : (t === "IMG" ? "[image without text]" : ""));
162       if (t === "CANVAS" && !label) emit("[canvas without text: needs screenshot]");
163       if (block) flush();
164       return;
165     }
166     if (el.getAttribute("data-label") && !el.textContent.trim()) emit(el.getAttribute("data-label"));
167     if (t === "TIME" && el.getAttribute("datetime")) { emit(`${clean(el.textContent)} (${el.getAttribute("datetime")})`); return; }
168     if (role === "tooltip") { emit(`[tooltip: ${clean(el.textContent)}]`); return; }
169     if (t === "TR") {
170       const cells = [...el.children].filter((c) => c.tagName === "TD" || c.tagName === "TH");
171       const saved = out.length;
172       const texts = cells.map((c) => {
173         const before = out.length; line = [];
174         orderedChildren(c).forEach((k) => walk(k, false));
175         flush();
176         const parts = out.splice(before);
177         return parts.join(" ; ");
178       });
179       out.length = saved;
180       out.push("| " + texts.join(" | ") + " |");
181       return;
182     }
183     const extra = describedTexts(el);
184     orderedChildren(el).forEach((k) => walk(k, false));
185     if (extra.length) emit(`[info: ${extra.join(" / ")}]`);
186     if (block) flush();
187   };
188 
189   walk(document.body || document.documentElement, false);
190   flush();
191   const tz = (document.body?.innerText.match(/Zeit(?:zone|angaben)\s*:\s*([A-Za-z_\/]+|UTC)/) || [])[1];
192   return { text: out.join("\n"), refs: n, title: document.title, timezone: tz || null };
193 }

